SELECT o.order_id AS orderId, o.product_id AS productId, p.title AS productTitle, p.cover_url AS coverUrl, o.price AS price, CASE o.status WHEN 1 THEN 'PENDING' WHEN 2 THEN 'PAID' WHEN 3 THEN 'CANCELLED' ELSE 'UNKNOWN' END AS status, o.source AS source, o.created_at AS createdAt FROM t_order o LEFT JOIN t_product p ON p.id = o.product_id WHERE o.user_id = #{userId}
AND o.status = #{status}
ORDER BY o.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM t_order
WHERE user_id = #{userId}

    AND status = #{status}
